package br.com.erp;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class SalePaymentTest extends SaleFixture {
 String bank;
 @BeforeEach void bank()throws Exception{bank=postApi("/api/v1/treasury/accounts",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"code","BANK","name","Banco","kind","BANK"),201).get("id").asText();}
 Map<String,Object> pay(String method,String amount,String tendered){var p=new HashMap<String,Object>();p.put("method",method);p.put("amount",amount);p.put("tendered",tendered);if(!method.equals("CASH")){p.put("accountId",bank);p.put("reference","Comprovante "+method+" "+UUID.randomUUID());p.put("confirmed",true);}return p;}
 Map<String,Object> mixed(UUID key,List<?> payments){return Map.of("requestId",key,"sessionId",session,"items",List.of(item(product,"2","10.25")),"payments",payments);}
 JsonNode mixedSale()throws Exception{return sell(mixed(UUID.randomUUID(),List.of(pay("CASH","5.50","10"),pay("PIX","10","10"),pay("BANK_TRANSFER","5","5"))),201);}
 Map<String,Object> cancelBody(UUID key,long version,boolean confirmed){return Map.of("requestId",key,"version",version,"note","Devolução integral conferida","externalRefundsConfirmed",confirmed);}
 JsonNode cancel(JsonNode sale,Object body,int status)throws Exception{return postApi("/api/v1/pos/sales/"+sale.get("id").asText()+"/cancel",auth,body,status);}
 BigDecimal bankBalance(){return db.queryForObject("SELECT balance FROM treasury_account WHERE tenant_id=? AND id=?",BigDecimal.class,tenant,UUID.fromString(bank));}
 @Test void mixedPaymentsPreserveEachMethodAndCreditCorrectAccounts()throws Exception{var s=mixedSale();money("20.50",s.get("total"));money("25",s.get("tendered"));money("4.50",s.get("changeAmount"));assertEquals(3,s.get("payments").size());assertEquals(0,new BigDecimal("5.50").compareTo(balance()));assertEquals(0,new BigDecimal("15").compareTo(bankBalance()));assertEquals(3,count("treasury_operation"));assertEquals(0,new BigDecimal("8").compareTo(quantity(product)));}
 @Test void nonCashOnlySaleDoesNotIncreaseDrawer()throws Exception{sell(mixed(UUID.randomUUID(),List.of(pay("PIX","20.50","20.50"))),201);assertEquals(0,balance().signum());assertEquals(0,new BigDecimal("20.50").compareTo(bankBalance()));assertEquals(1,getApi("/api/v1/pos/cash-sessions/"+session,auth,200).get("version").asInt());}
 @Test void legacySaleGetsOnePaymentAndRemainsReplayCompatible()throws Exception{var body=input(UUID.randomUUID(),"1","10.25","20");var sale=sell(body,201);assertEquals(1,sale.get("payments").size());assertEquals("CASH",sale.get("payments").get(0).get("method").asText());assertEquals(sale,sell(body,201));}
 @Test void incompleteExcessAndUnconfirmedPaymentsAreRejected()throws Exception{sell(mixed(UUID.randomUUID(),List.of(pay("CASH","20","20"))),400);sell(mixed(UUID.randomUUID(),List.of(pay("CASH","21","21"))),400);var p=pay("PIX","20.50","20.50");p.put("confirmed",false);sell(mixed(UUID.randomUUID(),List.of(p)),400);p.put("confirmed",true);p.put("reference"," ");sell(mixed(UUID.randomUUID(),List.of(p)),400);assertEquals(0,count("pos_sale"));assertEquals(1,count("stock_operation"));}
 @Test void changeOnlyOnCashAndAmbiguousInputsAreRejected()throws Exception{sell(mixed(UUID.randomUUID(),List.of(pay("PIX","20.50","21"))),400);sell(mixed(UUID.randomUUID(),List.of(pay("CASH","10","10"),pay("CASH","10.50","11"))),400);var body=new HashMap<>(mixed(UUID.randomUUID(),List.of(pay("CASH","20.50","21"))));body.put("tendered","21");sell(body,400);assertEquals(0,count("pos_sale"));}
 @Test void paymentReplayRevalidatesBankScopeAndConflictingPayloadFails()throws Exception{UUID key=UUID.randomUUID();var body=mixed(key,List.of(pay("CASH","5.50","10"),pay("PIX","15","15")));var s=sell(body,201);assertEquals(s,sell(body,201));sell(mixed(key,List.of(pay("PIX","20.50","20.50"))),409);UUID other=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","B","name","Outra"),201).get("id").asText());db.update("UPDATE treasury_account SET branch_id=? WHERE tenant_id=? AND id=?",other,tenant,UUID.fromString(bank));UUID user=db.queryForObject("SELECT id FROM app_user WHERE tenant_id=?",UUID.class,tenant);db.update("UPDATE app_user SET all_branches=FALSE WHERE tenant_id=?",tenant);db.update("INSERT INTO user_branch_access(tenant_id,user_id,branch_id) VALUES(?,?,?)",tenant,user,branch);sell(body,404);assertEquals(1,count("pos_sale"));}
 @Test void bankMustBelongToCashBranchAndCannotBeDrawer()throws Exception{var p=pay("PIX","20.50","20.50");p.put("accountId",account);sell(mixed(UUID.randomUUID(),List.of(p)),400);UUID other=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","B","name","Outra"),201).get("id").asText());db.update("UPDATE treasury_account SET branch_id=? WHERE tenant_id=? AND id=?",other,tenant,UUID.fromString(bank));sell(mixed(UUID.randomUUID(),List.of(pay("PIX","20.50","20.50"))),400);}
 @Test void cancellationReturnsStockAtOriginalCostAndRefundsEachPayment()throws Exception{var sale=mixedSale();var body=cancelBody(UUID.randomUUID(),0,true);var result=cancel(sale,body,200);assertEquals("CANCELLED",result.get("status").asText());assertEquals(1,result.get("version").asInt());assertEquals(0,balance().signum());assertEquals(0,bankBalance().signum());assertEquals(0,BigDecimal.TEN.compareTo(quantity(product)));assertEquals(0,new BigDecimal("3").compareTo(db.queryForObject("SELECT average_cost FROM stock_balance WHERE tenant_id=? AND warehouse_id=? AND product_id=?",BigDecimal.class,tenant,UUID.fromString(warehouse),UUID.fromString(product))));for(var p:result.get("payments")){assertEquals("REFUNDED",p.get("status").asText());assertFalse(p.get("reversalOperationId").isNull());}assertEquals(result,cancel(sale,body,200));assertEquals(6,count("treasury_operation"));assertEquals(3,count("stock_operation"));assertEquals(2,getApi("/api/v1/pos/cash-sessions/"+session,auth,200).get("version").asInt());}
 @Test void cancellationNeedsExplicitExternalRefundConfirmationAndCurrentVersion()throws Exception{var sale=mixedSale();cancel(sale,cancelBody(UUID.randomUUID(),0,false),400);cancel(sale,cancelBody(UUID.randomUUID(),1,true),409);assertEquals(0,new BigDecimal("8").compareTo(quantity(product)));assertEquals("COMPLETED",getApi("/api/v1/pos/sales/"+sale.get("id").asText(),auth,200).get("status").asText());}
 @Test void insufficientRefundBalanceRollsBackStockPaymentsAndSale()throws Exception{var sale=mixedSale();postApi("/api/v1/treasury/movements",auth,Map.of("requestId",UUID.randomUUID(),"sourceId",bank,"amount","15","note","Saída posterior de teste"),200);cancel(sale,cancelBody(UUID.randomUUID(),0,true),409);assertEquals(0,new BigDecimal("8").compareTo(quantity(product)));assertEquals(0,new BigDecimal("5.50").compareTo(balance()));assertEquals(2,count("stock_operation"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM pos_sale_payment WHERE tenant_id=? AND status='REFUNDED'",Long.class,tenant));}
 @Test void inactiveProductCanReturnButChangedUnitOrInactiveWarehouseCannot()throws Exception{var sale=mixedSale();db.update("UPDATE product SET unit='UN' WHERE tenant_id=? AND id=?",tenant,UUID.fromString(product));cancel(sale,cancelBody(UUID.randomUUID(),0,true),409);db.update("UPDATE product SET unit='KG',active=FALSE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(product));db.update("UPDATE warehouse SET active=FALSE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(warehouse));cancel(sale,cancelBody(UUID.randomUUID(),0,true),404);db.update("UPDATE warehouse SET active=TRUE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(warehouse));cancel(sale,cancelBody(UUID.randomUUID(),0,true),200);}
 @Test void closedShiftRejectsNewCancellationButReplaysOriginalCancellation()throws Exception{var sale=mixedSale();var body=cancelBody(UUID.randomUUID(),0,true);var cancelled=cancel(sale,body,200);postApi("/api/v1/pos/cash-sessions/"+session+"/close",auth,Map.of("requestId",UUID.randomUUID(),"version",2,"countedAmount","0","note","Fechamento do teste"),200);assertEquals(cancelled,cancel(sale,body,200));cancel(sale,cancelBody(UUID.randomUUID(),0,true),409);}
 @Test void cancellationIsSeparatelyAuthorizedAndTenantScoped()throws Exception{var sale=mixedSale();db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='pos:cancel'",tenant);cancel(sale,cancelBody(UUID.randomUUID(),0,true),403);String other="other-"+UUID.randomUUID();provisioning.create("Outra",other,"Admin","admin@example.com",password);postApi("/api/v1/pos/sales/"+sale.get("id").asText()+"/cancel",token(other),cancelBody(UUID.randomUUID(),0,true),404);}
 @Test void sameCancelKeyCannotBeReusedForOtherSaleOrNote()throws Exception{var sale=mixedSale();UUID key=UUID.randomUUID();cancel(sale,cancelBody(key,0,true),200);var second=mixedSale();cancel(second,cancelBody(key,0,true),409);var changed=new HashMap<>(cancelBody(key,0,true));changed.put("note","Outra justificativa");cancel(sale,changed,409);assertEquals(2,count("pos_sale"));}
 @Test void externalProofCannotBeReusedAcrossSalesEvenAfterRefund()throws Exception{var body=mixed(UUID.randomUUID(),List.of(pay("PIX","20.50","20.50")));var sale=sell(body,201);var duplicate=new HashMap<>(body);duplicate.put("requestId",UUID.randomUUID());sell(duplicate,409);cancel(sale,cancelBody(UUID.randomUUID(),0,true),200);sell(duplicate,409);assertEquals(1,count("pos_sale"));}
 @Test void cashCancellationNeedsNoBankRefundConfirmation()throws Exception{var sale=sell(input(UUID.randomUUID(),"1","10.25","20"),201);var cancelled=cancel(sale,cancelBody(UUID.randomUUID(),0,false),200);assertEquals("CANCELLED",cancelled.get("status").asText());assertEquals(0,balance().signum());assertEquals(0,BigDecimal.TEN.compareTo(quantity(product)));}
 @Test void bankOverflowAfterCashCreditRollsBackAllPaymentsAndStock()throws Exception{db.update("UPDATE treasury_account SET balance=99999999999999999.99 WHERE tenant_id=? AND id=?",tenant,UUID.fromString(bank));sell(mixed(UUID.randomUUID(),List.of(pay("CASH","5.50","10"),pay("PIX","15","15"))),409);assertEquals(0,balance().signum());assertEquals(0,count("pos_sale_payment"));assertEquals(0,count("treasury_operation"));assertEquals(0,BigDecimal.TEN.compareTo(quantity(product)));}
 @Test void cancellationPreservesOriginalCostAfterAnotherReceipt()throws Exception{var sale=mixedSale();postApi("/api/v1/inventory/movements",auth,Map.of("operationId",UUID.randomUUID(),"warehouseId",warehouse,"productId",product,"type","RECEIPT","quantity","2","unitCost","9","reason","Entrada posterior mais cara"),200);cancel(sale,cancelBody(UUID.randomUUID(),0,true),200);assertEquals(0,new BigDecimal("12").compareTo(quantity(product)));assertEquals(0,new BigDecimal("4").compareTo(db.queryForObject("SELECT average_cost FROM stock_balance WHERE tenant_id=? AND warehouse_id=? AND product_id=?",BigDecimal.class,tenant,UUID.fromString(warehouse),UUID.fromString(product))));}
 @Test void closeRacingWithCancellationCannotFreezeWrongDrawerAmount()throws Exception{var sale=mixedSale();try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var gate=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{gate.await();return status("/api/v1/pos/sales/"+sale.get("id").asText()+"/cancel",cancelBody(UUID.randomUUID(),0,true));});var b=pool.submit(()->{gate.await();return status("/api/v1/pos/cash-sessions/"+session+"/close",Map.of("requestId",UUID.randomUUID(),"version",1,"countedAmount","5.50","note","Fechamento concorrente"));});gate.countDown();var results=new ArrayList<>(List.of(a.get(30,java.util.concurrent.TimeUnit.SECONDS),b.get(30,java.util.concurrent.TimeUnit.SECONDS)));Collections.sort(results);assertEquals(List.of(200,409),results);}var s=getApi("/api/v1/pos/cash-sessions/"+session,auth,200);if(s.get("status").asText().equals("CLOSED")){money("5.50",s.get("expectedAmount"));assertEquals(0,new BigDecimal("8").compareTo(quantity(product)));}else{assertEquals(0,balance().signum());assertEquals(0,BigDecimal.TEN.compareTo(quantity(product)));}}
 @Test void concurrentCancellationHasOneRefundAndOneStockReturn()throws Exception{var sale=mixedSale();var body=cancelBody(UUID.randomUUID(),0,true);String path="/api/v1/pos/sales/"+sale.get("id").asText()+"/cancel";try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var gate=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{gate.await();return status(path,body);});var b=pool.submit(()->{gate.await();return status(path,body);});gate.countDown();assertEquals(200,a.get(30,java.util.concurrent.TimeUnit.SECONDS));assertEquals(200,b.get(30,java.util.concurrent.TimeUnit.SECONDS));}assertEquals(3,count("stock_operation"));assertEquals(6,count("treasury_operation"));assertEquals(0,balance().signum());}
}
